
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_w94_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_w94", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.830032067357704e-02, -6.748576506619317e-02, -6.626370635882881e-02, -6.440180834010002e-02, -6.151236572484308e-02, -5.694812313865256e-02, -4.970387678325068e-02, -3.867064631827115e-02, -2.433572473489910e-02, -1.164544372868221e-02, -7.571432142101675e-03, -4.261190805664042e-02, -5.473694956562458e-02, -3.566387619076569e-02, -1.290455001976434e-02, -2.229479674876931e-03, -1.579478759287635e-04, -3.519618919186107e-06, -1.526600210853332e-08, -6.889177587841229e-12]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


